class Solution:
    def findMaximumLength(self, nums: List[int]) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        dp = [0] * (n + 1)
        last = [0] * (n + 1)
        dq = deque([0])

        for i in range(1, n + 1):
            while len(dq) > 1 and pref[dq[1]] + last[dq[1]] <= pref[i]:
                dq.popleft()
            j = dq[0]
            dp[i] = dp[j] + 1
            last[i] = pref[i] - pref[j]
            while dq and pref[dq[-1]] + last[dq[-1]] >= pref[i] + last[i]:
                dq.pop()
            dq.append(i)
        return dp[n]

class Solution {
public:
    int findMaximumLength(vector<int>& nums) {
        int n = nums.size();
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
        vector<int> dp(n + 1, 0);
        vector<long long> last(n + 1, 0);
        deque<int> dq;
        dq.push_back(0);
        for (int i = 1; i <= n; i++) {
            while (dq.size() > 1 && pref[dq[1]] + last[dq[1]] <= pref[i]) {
                dq.pop_front();
            }
            int j = dq.front();
            dp[i] = dp[j] + 1;
            last[i] = pref[i] - pref[j];
            while (!dq.empty() && pref[dq.back()] + last[dq.back()] >= pref[i] + last[i]) {
                dq.pop_back();
            }
            dq.push_back(i);
        }
        return dp[n];
    }
};

class Solution {
    public int findMaximumLength(int[] nums) {
        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
        int[] dp = new int[n + 1];
        long[] last = new long[n + 1];
        int[] dq = new int[n + 2];
        int head = 0, tail = 0;
        dq[tail++] = 0;
        for (int i = 1; i <= n; i++) {
            while (tail - head > 1 && pref[dq[head + 1]] + last[dq[head + 1]] <= pref[i]) {
                head++;
            }
            int j = dq[head];
            dp[i] = dp[j] + 1;
            last[i] = pref[i] - pref[j];
            while (tail > head && pref[dq[tail - 1]] + last[dq[tail - 1]] >= pref[i] + last[i]) {
                tail--;
            }
            dq[tail++] = i;
        }
        return dp[n];
    }
}

