    const n = nums.length;
    const pref = new BigInt64Array(n + 1);
    for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + BigInt(nums[i]);
    const dp = new Int32Array(n + 1);
    const last = new BigInt64Array(n + 1);
    const dq = new Int32Array(n + 2);
    let head = 0, tail = 0;
    dq[tail++] = 0;
    for (let i = 1; i <= n; i++) {
        while (tail - head > 1 && pref[dq[head + 1]] + last[dq[head + 1]] <= pref[i]) {
            head++;
        }
        const j = dq[head];
        dp[i] = dp[j] + 1;
        last[i] = pref[i] - pref[j];
        while (tail > head && pref[dq[tail - 1]] + last[dq[tail - 1]] >= pref[i] + last[i]) {
            tail--;
        }
        dq[tail++] = i;
    }
    return dp[n];
};
